const req = $('Interview Assist Webhook').first().json;
const key = $input.first().json || {};
const rid = 'req_' + $execution.id;
const fail = (status, code, message) => [{ json: { valid: false, status_code: status, response: { ok: false, request_id: rid, error: { code, message } } } }];
if (!key.api_key_sha256 || key.active !== true || key.client !== 'extension') return fail(401, 'UNAUTHORIZED', 'Missing or invalid API key for this endpoint');
const body = (req.body && typeof req.body === 'object' && !Array.isArray(req.body)) ? req.body : {};
const errors = [];
const ID = /^[A-Za-z0-9_-]{1,64}$/;
const LIMITS = { job_role: 120, resume_summary: 4000, current_transcript_chunk: 3000, previous_chunk: 3000 };
const ALLOWED = ['candidate_id', 'job_competencies', 'job_role', 'resume_summary', 'current_transcript_chunk', 'previous_chunk'];
for (const k of Object.keys(body)) if (!ALLOWED.includes(k)) errors.push('unknown field: ' + k);
if (!ID.test(String(body.candidate_id || ''))) errors.push('candidate_id must match ^[A-Za-z0-9_-]{1,64}');
for (const k of ['job_role', 'resume_summary', 'current_transcript_chunk']) {
  if (typeof body[k] !== 'string' || !body[k].trim()) errors.push(k + ' is required');
}
for (const [k, max] of Object.entries(LIMITS)) {
  if (body[k] != null && String(body[k]).length > max) errors.push(k + ' exceeds ' + max + ' characters');
}
if (body.previous_chunk != null && typeof body.previous_chunk !== 'string') errors.push('previous_chunk must be a string');
let comps = [];
if (body.job_competencies != null) {
  const ok = Array.isArray(body.job_competencies) && body.job_competencies.length <= 15 && body.job_competencies.every(c => typeof c === 'string' && c.length <= 80);
  if (!ok) errors.push('job_competencies must be an array of at most 15 strings of 80 characters'); else comps = body.job_competencies;
}
if (errors.length) return fail(400, 'VALIDATION_ERROR', errors.join('; '));
return [{ json: { valid: true, request_id: rid, candidate_id: body.candidate_id, fields: {
  job_role: body.job_role,
  job_competencies: comps.join('; '),
  resume_summary: body.resume_summary,
  previous_chunk: body.previous_chunk || '',
  current_transcript_chunk: body.current_transcript_chunk
} } }];

const g = $input.first().json;
const v = $('Authorize and Validate').first().json;
const guard = $('Run sub-guard').first().json;
const str = (x, n) => String(x ?? '').replace(/<[^>]*>/g, '').trim().slice(0, n);
const SEV = ['none', 'low', 'medium', 'high'];
const flags = (guard.flags || []).slice();
const o = (g && g.ok && g.out && typeof g.out === 'object') ? g.out : null;
let data = { candidate_id: v.candidate_id, weakness_detected: false, competency: '', severity: 'none', detected_gap: '', evidence: '', suggested_probing_questions: [] };
if (!o) {
  flags.push({ field: 'model', type: (g && g.error) || 'ai_unavailable' });
} else {
  let qs = Array.isArray(o.suggested_probing_questions) ? o.suggested_probing_questions.map(q => str(q, 200)).filter(Boolean).slice(0, 3) : [];
  const weak = o.weakness_detected === true && qs.length > 0;
  if (!weak) qs = [];
  data = {
    candidate_id: v.candidate_id,
    weakness_detected: weak,
    competency: weak ? str(o.competency, 80) : '',
    severity: weak ? (SEV.includes(o.severity) && o.severity !== 'none' ? o.severity : 'low') : 'none',
    detected_gap: weak ? str(o.detected_gap, 200) : '',
    evidence: weak ? str(o.evidence, 150) : '',
    suggested_probing_questions: qs
  };
  if (o.injection_attempt_observed === true) flags.push({ field: 'current_transcript_chunk', type: 'model_observed_injection' });
}
const injection = flags.some(f => f.field !== 'model');
return [{ json: { status_code: 200, response: { ok: true, request_id: v.request_id, data, security: { injection_suspected: injection, flags } } } }];
